    49  static bool mqtt_send_header(struct mg_connection *c, uint8_t cmd,
    50                               uint8_t flags, uint32_t len) {
    51    uint8_t buf[1 + sizeof(len)], *vlen = &buf[1];
    52    buf[0] = (uint8_t) ((cmd << 4) | flags);
    53    do {
    54      *vlen = len % 0x80;
    55      len /= 0x80;
    56      if (len > 0) *vlen |= 0x80;
    57      vlen++;
    58    } while (len > 0 && vlen < &buf[sizeof(buf)]);
    59    return mg_send(c, buf, (size_t) (vlen - buf));
    60  }
