   271    struct mg_str cid = opts->client_id;
   272    size_t total_len = 7 + 1 + 2 + 2;
   273    uint8_t hdr[8] = {0, 4, 'M', 'Q', 'T', 'T', 0, 0};
   274    hdr[6] = opts->version;
